'use client'
import React, { useEffect, useRef, useState } from 'react'
import gsap from 'gsap'
import { BasePhaseProps } from '@/lib/types'
import WantedStarsHUD from './WantedStarsHUD'

const IMAGES = ['/images/loading_1.jpeg', '/images/loading_2.jpeg', '/images/loading_3.jpeg']

const TIPS = [
    'LOS SANTOS — WHERE REPUTATIONS ARE BUILT IN CODE',
    'STAY ALERT: EVERY LINE OF CODE MATTERS IN THE OPEN WORLD',
    'MODERN PROBLEMS REQUIRE DISTRIBUTED ARCHITECTURES',
    'INVEST IN YOUR TECH STACK, NOT JUST YOUR AMMO',
    'EXPLORE THE FULL MAP TO UNCOVER HIDDEN OPERATIONS',
]

const STATUS_STEPS = [
    { text: 'STREAMING LOS SANTOS ASSETS', pct: '28%' },
    { text: 'COMPILING SHADERS & LIGHTING', pct: '56%' },
    { text: 'ESTABLISHING SECURE PROTOCOL', pct: '84%' },
    { text: 'SYNCHRONIZING DEVELOPER INTEL', pct: '98%' },
    { text: 'OPERATION READY', pct: '100%' },
]

export default function LoadingFlow({ onComplete, sounds }: BasePhaseProps) {
    const containerRef = useRef<HTMLDivElement | null>(null)
    const imgs = useRef<(HTMLImageElement | null)[]>([])
    const barRef = useRef<HTMLDivElement | null>(null)
    const spinnerRef = useRef<SVGSVGElement | null>(null)
    const [tipIdx, setTipIdx] = useState<number>(0)
    const [statusIdx, setStatusIdx] = useState<number>(0)

    useEffect(() => {
        try {
            if (sounds?.ambience) {
                if (!sounds.ambience.playing()) {
                    sounds.ambience.volume(0.45)
                    sounds.ambience.loop(true)
                    sounds.ambience.play()
                }
            }
        } catch (e) {
            console.warn('Audio ambience notice:', e)
        }

        // Animate first image with slow Ken Burns drift
        if (imgs.current[0]) {
            gsap.fromTo(
                imgs.current[0],
                { scale: 1.0, x: 0, opacity: 1 },
                { scale: 1.08, x: -15, duration: 6, ease: 'sine.out' }
            )
        }

        // GTA Spinner rotation
        if (spinnerRef.current) {
            gsap.to(spinnerRef.current, {
                rotation: 360,
                duration: 1.8,
                repeat: -1,
                ease: 'linear',
            })
        }

        // Smooth image cycling
        let current = 0
        const cycleImages = () => {
            const next = (current + 1) % IMAGES.length
            if (imgs.current[current]) {
                gsap.to(imgs.current[current], {
                    opacity: 0,
                    duration: 1.4,
                    ease: 'power2.inOut',
                })
            }
            if (imgs.current[next]) {
                gsap.fromTo(
                    imgs.current[next],
                    { opacity: 0, scale: 1.0, x: 10 },
                    {
                        opacity: 1,
                        scale: 1.08,
                        x: -10,
                        duration: 6,
                        ease: 'sine.out',
                    }
                )
            }
            current = next
        }
        const imgInterval = setInterval(cycleImages, 5500)

        // Tip rotation
        const tipInterval = setInterval(() => {
            setTipIdx((p) => (p + 1) % TIPS.length)
        }, 4500)

        // Loading bar progress
        const barTl = gsap.timeline({
            onComplete: () => {
                clearInterval(imgInterval)
                clearInterval(tipInterval)
                setTimeout(onComplete, 800)
            },
        })

        if (barRef.current) {
            barTl.to(barRef.current, {
                width: '28%',
                duration: 2.2,
                ease: 'power2.out',
                onStart: () => setStatusIdx(0),
            })
            barTl.to({}, { duration: 0.6 })
            barTl.to(barRef.current, {
                width: '56%',
                duration: 2.8,
                ease: 'power1.inOut',
                onStart: () => setStatusIdx(1),
            })
            barTl.to({}, { duration: 0.8 })
            barTl.to(barRef.current, {
                width: '84%',
                duration: 3.2,
                ease: 'power1.out',
                onStart: () => setStatusIdx(2),
            })
            barTl.to(barRef.current, {
                width: '98%',
                duration: 2.0,
                ease: 'power2.out',
                onStart: () => setStatusIdx(3),
            })
            barTl.to({}, { duration: 0.5 })
            barTl.to(barRef.current, {
                width: '100%',
                duration: 0.6,
                ease: 'power3.in',
                onStart: () => setStatusIdx(4),
            })
        }

        return () => {
            barTl.kill()
            clearInterval(imgInterval)
            clearInterval(tipInterval)
            imgs.current.forEach((img) => {
                if (img) gsap.killTweensOf(img)
            })
            if (barRef.current) gsap.killTweensOf(barRef.current)
            if (spinnerRef.current) gsap.killTweensOf(spinnerRef.current)
        }
    }, [onComplete, sounds])

    const currentStatus = STATUS_STEPS[statusIdx] || STATUS_STEPS[0]

    return (
        <div
            ref={containerRef}
            style={{
                position: 'fixed',
                inset: 0,
                background: '#000',
                zIndex: 100,
                overflow: 'hidden',
                userSelect: 'none',
            }}
        >
            {/* Background Slideshow with Smooth Ken Burns */}
            {IMAGES.map((src, i) => (
                <img
                    key={src}
                    ref={(el) => {
                        imgs.current[i] = el
                    }}
                    src={src}
                    alt="Loading artwork"
                    style={{
                        position: 'absolute',
                        inset: '-5%',
                        width: '110%',
                        height: '110%',
                        objectFit: 'cover',
                        opacity: i === 0 ? 1 : 0,
                        filter: 'brightness(0.9) contrast(1.1)',
                        transformOrigin: 'center center',
                    }}
                />
            ))}

            <div className="heavy-vignette" />
            <div className="noise-overlay" />
            <div className="crt-scanlines" />

            {/* Top Right GTA Wanted Stars HUD */}
            <div
                style={{
                    position: 'absolute',
                    top: 36,
                    right: 48,
                    zIndex: 110,
                    display: 'flex',
                    flexDirection: 'column',
                    alignItems: 'flex-end',
                    gap: '6px',
                }}
            >
                <div
                    style={{
                        fontFamily: 'ChaletComprime1960, "Barlow Condensed", sans-serif',
                        fontSize: '0.85rem',
                        letterSpacing: '0.25em',
                        color: 'rgba(255,255,255,0.7)',
                        textTransform: 'uppercase',
                    }}
                >
                    ONLINE // SAN ANDREAS
                </div>
                <WantedStarsHUD count={5} size={18} />
            </div>

            {/* Tip text */}
            <div
                className="loading-tip-container"
                style={{
                    position: 'absolute',
                    bottom: 120,
                    left: 54,
                    right: 54,
                    zIndex: 110,
                    maxWidth: '850px',
                }}
            >
                <div
                    style={{
                        fontFamily: 'ChaletComprime1960, "Barlow Condensed", sans-serif',
                        fontSize: '0.75rem',
                        letterSpacing: '0.3em',
                        color: '#f5a623',
                        marginBottom: '6px',
                        textTransform: 'uppercase',
                    }}
                >
                    INTEL BRIEFING
                </div>
                <p
                    key={tipIdx}
                    style={{
                        fontFamily: 'ChaletComprime1960, "Barlow Condensed", sans-serif',
                        fontSize: 'clamp(0.95rem, 2.2vw, 1.25rem)',
                        letterSpacing: '0.2em',
                        lineHeight: 1.4,
                        textTransform: 'uppercase',
                        color: '#ffffff',
                        textShadow: '0 2px 10px rgba(0,0,0,0.9)',
                        transition: 'opacity 0.5s ease',
                    }}
                >
                    {TIPS[tipIdx]}
                </p>
            </div>

            {/* Bottom Loading Bar & Spinner */}
            <div
                className="loading-bar-container"
                style={{
                    position: 'absolute',
                    bottom: 45,
                    left: 54,
                    right: 54,
                    zIndex: 120,
                }}
            >
                <div
                    style={{
                        display: 'flex',
                        justifyContent: 'space-between',
                        alignItems: 'center',
                        marginBottom: '8px',
                        fontFamily: 'ChaletComprime1960, "Barlow Condensed", sans-serif',
                        fontSize: '0.85rem',
                        letterSpacing: '0.2em',
                        color: 'rgba(255,255,255,0.7)',
                        textTransform: 'uppercase',
                    }}
                >
                    <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
                        <svg
                            ref={spinnerRef}
                            width="14"
                            height="14"
                            viewBox="0 0 24 24"
                            fill="none"
                            stroke="#f5a623"
                            strokeWidth="3"
                        >
                            <circle cx="12" cy="12" r="9" strokeDasharray="30 15" />
                        </svg>
                        <span>{currentStatus.text}</span>
                    </div>
                    <span style={{ color: '#f5a623', fontWeight: 'bold' }}>{currentStatus.pct}</span>
                </div>

                <div
                    style={{
                        height: '4px',
                        background: 'rgba(255,255,255,0.18)',
                        width: '100%',
                        overflow: 'hidden',
                    }}
                >
                    <div
                        ref={barRef}
                        style={{
                            height: '100%',
                            width: '0%',
                            background: '#ffffff',
                            boxShadow: '0 0 14px rgba(255,255,255,0.9)',
                        }}
                    />
                </div>
            </div>
        </div>
    )
}
